from rdkit import Chem
from rdkit.Chem import rdCIPLabeler
import numpy as np, sys
smi = "[C@@H]1(Nc2ccccc2)CCC=CC3=C1[Pd]34[P](c5ccccc5)(c5ccccc5)c5cccc6c5Oc7c(C6(C)C)cccc7[P]4(c8ccccc8)c8ccccc8"
m = Chem.AddHs(Chem.MolFromSmiles(smi))
ref = Chem.MolFromXYZFile(sys.argv[1])
pos = ref.GetConformer().GetPositions()
c = Chem.Conformer(m.GetNumAtoms())
for i in range(m.GetNumAtoms()): c.SetAtomPosition(i,pos[i].tolist())
m.RemoveAllConformers(); m.AddConformer(c)
Chem.AssignStereochemistryFrom3D(m)
rdCIPLabeler.AssignCIPLabels(m)
for a in m.GetAtoms():
    if a.HasProp('_CIPCode'): print("CIP",a.GetIdx(),a.GetProp('_CIPCode'))
for b in m.GetBonds():
    i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx(); d=np.linalg.norm(pos[i]-pos[j])
    if d>2.55: print("long",i,m.GetAtomWithIdx(i).GetSymbol(),j,m.GetAtomWithIdx(j).GetSymbol(),round(d,2))
# min nonbonded
from itertools import combinations
adj={ (b.GetBeginAtomIdx(),b.GetEndAtomIdx()) for b in m.GetBonds()}
mind=9
for i,j in combinations(range(m.GetNumAtoms()),2):
    if (i,j) in adj or (j,i) in adj: continue
    d=np.linalg.norm(pos[i]-pos[j])
    if d<1.5: print("clash",i,j,round(d,2))
for i in (12,13,15,44): print("Pd-",i,round(np.linalg.norm(pos[14]-pos[i]),2))
print("C12=C13",round(np.linalg.norm(pos[12]-pos[13]),2))
